package com.finsight.backend.service;

import com.finsight.backend.dto.alert.AlertResponse;

/**
 * Spending alerts for an uploaded file. Alerts are generated by the AI service, stored
 * against the latest analysis of the upload, and can be marked read. Implementation:
 * AlertServiceImpl.
 */
public interface AlertService {

    /**
     * Run the AI alert agent for the upload, replace any existing alerts and return
     * the saved result.
     */
    AlertResponse generateAlerts(Long uploadHistoryId);

    /**
     * Return the saved alerts (and unread count) for the upload.
     */
    AlertResponse getAlerts(Long uploadHistoryId);

    /**
     * Mark every alert of the upload as read.
     */
    AlertResponse markAllAsRead(Long uploadHistoryId);

    /**
     * Mark a single alert as read.
     */
    AlertResponse markAsRead(Long uploadHistoryId, Long alertId);
}
